html:
{%- import "erpnext/templates/print_formats/report_print_macros.html" as rp -%}
{%- set show_company = no_letterhead if no_letterhead is defined else not letter_head -%}
{%- set vouchers = [] -%}
{%- set lines = {} -%}
{%- for row in data if row is mapping -%}
	{%- if row.parent_voucher -%}
		{%- set ignore = lines.setdefault(row.parent_voucher, []).append(row) -%}
	{%- elif row.voucher_no -%}
		{%- set ignore = vouchers.append(row) -%}
	{%- endif -%}
{%- endfor -%}
{{ rp.styles() }}
<div class="rpf">
	{%- if show_company %}{{ rp.company_header(filters.company) }}{% endif %}
	{{ rp.head(_("Day Book"), rp.period(filters.from_date, filters.to_date) if filters.from_date != filters.to_date else rp.date(filters.from_date), _(filters.voucher_type) if filters.voucher_type else None) }}
	<table class="rpf-grid rpf-vouchers">
		<colgroup><col style="width: 80px"><col><col style="width: 120px"><col style="width: 144px"><col style="width: 120px"><col style="width: 120px"></colgroup>
		<thead>
			<tr>
				<th>{{ _("Date") }}</th>
				<th>{{ _("Particulars") }}</th>
				<th>{{ _("Voucher Type") }}</th>
				<th>{{ _("Voucher No.") }}</th>
				<th class="num">{{ _("Debit") }}</th>
				<th class="num">{{ _("Credit") }}</th>
			</tr>
		</thead>
		<tbody>
			{%- set last = namespace(date=None) %}
			{%- for voucher in vouchers %}
			{%- set legs = lines.get(voucher.voucher) or [] %}
			<tr class="{{ 'voucher' if legs else '' }}">
				<td class="nowrap">{{ rp.date(voucher.posting_date) if voucher.posting_date != last.date else "" }}</td>
				<td class="clip">{{ rp.short(voucher.particulars, filters.company) }}</td>
				<td class="clip">{{ _(voucher.voucher_type) }}</td>
				<td class="clip muted">{{ voucher.voucher_no | e }}</td>
				<td class="num">{{ rp.money(voucher.debit) }}</td>
				<td class="num">{{ rp.money(voucher.credit) }}</td>
			</tr>
			{%- if filters.show_remarks and voucher.remarks %}
			<tr class="leg">
				<td></td>
				<td class="note narration">{{ voucher.remarks | e }}</td>
				<td></td>
				<td></td>
				<td></td>
				<td></td>
			</tr>
			{%- endif %}
			{%- for leg in legs %}
			<tr class="leg">
				<td></td>
				<td class="clip"><span class="muted">{{ rp.short(leg.particulars, filters.company) }}</span></td>
				<td></td>
				<td></td>
				<td class="num"><span class="muted">{{ rp.money(leg.debit) }}</span></td>
				<td class="num"><span class="muted">{{ rp.money(leg.credit) }}</span></td>
			</tr>
			{%- endfor %}
			{%- set last.date = voucher.posting_date %}
			{%- else %}
			<tr><td colspan="6" class="rpf-empty">{{ _("No vouchers in this period") }}</td></tr>
			{%- endfor %}
			{%- if vouchers and filters.voucher_type %}
			<tr class="total">
				<td></td>
				<td>{{ _("Total") }} · {{ (_("{0} voucher") if vouchers | length == 1 else _("{0} vouchers")).format(vouchers | length) }}</td>
				<td></td>
				<td></td>
				<td class="num"><span class="double">{{ rp.money(vouchers | map(attribute="debit") | map("float") | sum) }}</span></td>
				<td class="num"><span class="double">{{ rp.money(vouchers | map(attribute="credit") | map("float") | sum) }}</span></td>
			</tr>
			{%- endif %}
		</tbody>
	</table>
	{%- if vouchers and not filters.voucher_type %}<div class="rpf-meta rpf-caption">{{ (_("{0} voucher") if vouchers | length == 1 else _("{0} vouchers")).format(vouchers | length) }}</div>{% endif %}
	{{ rp.footnote() }}
</div>
